// NV-DXVK [WC staging]: copy FROM write-combined (WC) mapped GPU memory into
// cached system memory. Plain memcpy reads WC with ordinary loads — every
// load is an uncached memory transaction, ~300 MB/s effective. movntdqa
// (streaming load) is the instruction Intel/AMD provide specifically for
// reading WC: it fills a whole 64-byte line-fill buffer per transaction and
// streams at multi-GB/s. Measured motivation: the per-draw index-snapshot
// memcpy alone was ~64 ms/frame in TF2 ([Perf.SubmitDraw] indexSnap).
// movntdqa requires 16-byte-ALIGNED source addresses, so the unaligned head
// and tail fall back to memcpy; destination alignment is irrelevant
// (_mm_storeu_si128). Only the SOURCE being WC matters — dst is normal heap.
static void memcpyFromWC(void* dst, const void* src, size_t len) {
  uint8_t* d = static_cast<uint8_t*>(dst);
  const uint8_t* s = static_cast<const uint8_t*>(src);

  // Unaligned head: copy bytes until src reaches 16-byte alignment.
  const size_t misalign = reinterpret_cast<uintptr_t>(s) & 15u;
  if (misalign != 0) {
    const size_t head = std::min<size_t>(16u - misalign, len);
    std::memcpy(d, s, head);
    d += head; s += head; len -= head;
  }

  // Streaming body: 64 bytes (4x movntdqa) per iteration — one full
  // line-fill buffer — then a 16-byte loop for the remainder.
  while (len >= 64) {
    const __m128i* sv = reinterpret_cast<const __m128i*>(s);
    const __m128i v0 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 0));
    const __m128i v1 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 1));
    const __m128i v2 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 2));
    const __m128i v3 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 3));
    _mm_storeu_si128(reinterpret_cast<__m128i*>(d) + 0, v0);
    _mm_storeu_si128(reinterpret_cast<__m128i*>(d) + 1, v1);
    _mm_storeu_si128(reinterpret_cast<__m128i*>(d) + 2, v2);
    _mm_storeu_si128(reinterpret_cast<__m128i*>(d) + 3, v3);
    d += 64; s += 64; len -= 64;
  }
  while (len >= 16) {
    const __m128i v = _mm_stream_load_si128(
      const_cast<__m128i*>(reinterpret_cast<const __m128i*>(s)));
    _mm_storeu_si128(reinterpret_cast<__m128i*>(d), v);
    d += 16; s += 16; len -= 16;
  }

  // Unaligned tail.
  if (len != 0) {
    std::memcpy(d, s, len);
  }
}

// NV-DXVK [WC fused max-scan]: return max(index) read DIRECTLY out of
// write-combined mapped memory, with no staging copy.
//
// Why this exists. Sizing a draw's vertex range needs the largest index it
// references, and for TF2's DYNAMIC index buffers that value has to be
// recomputed every frame (the per-buffer memo is invalidated on every
// Map(DISCARD), by design — see LookupMaxIdx). The previous form staged the
// range with memcpyFromWC into a thread_local scratch and then ran a scalar
// max over the scratch: three passes over the same bytes (WC streaming read,
// scratch write, scratch read) to produce a single number. Folding the
// reduction into the streaming load leaves exactly ONE pass and no scratch —
// movntdqa still pulls a whole 64-byte line-fill per transaction (the entire
// point on WC memory), and _mm_max_epu16/_mm_max_epu32 fold each vector
// in-register for free alongside it.
//
// The result is bit-identical to the scalar scan it replaces; only the
// memory traffic changes. Do NOT "optimise" this into a sampled/partial scan:
// the max must be exact, because an undercount sizes the vertex buffer too
// small and the interleaver then reads out of bounds (mangled geometry/TDR).
static uint32_t maxIndexFromWC(const void* src, uint32_t count, uint32_t idxStride) {
  const uint8_t* const s = static_cast<const uint8_t*>(src);
  uint32_t maxSeen = 0;
  if (count == 0u)
    return 0u;

  auto scalarAt = [s, idxStride](uint32_t k) -> uint32_t {
    if (idxStride == 2u) {
      uint16_t v; std::memcpy(&v, s + size_t(k) * 2u, 2); return v;
    }
    uint32_t v; std::memcpy(&v, s + size_t(k) * 4u, 4); return v;
  };

  uint32_t i = 0;

  // movntdqa requires a 16-byte-aligned source, so consume WHOLE indices
  // until the pointer is aligned. A bindable D3D11 index buffer is always at
  // least stride-aligned, so that head is a whole number of indices; if it
  // somehow is not, fall back to a plain scalar scan (still exact).
  const size_t misalign = reinterpret_cast<uintptr_t>(s) & 15u;
  if (misalign != 0u) {
    const size_t headBytes = 16u - misalign;
    if ((headBytes % idxStride) != 0u) {
      for (; i < count; ++i) {
        const uint32_t v = scalarAt(i);
        if (v > maxSeen) maxSeen = v;
      }
      return maxSeen;
    }
    const uint32_t headCount =
      std::min<uint32_t>(static_cast<uint32_t>(headBytes / idxStride), count);
    for (; i < headCount; ++i) {
      const uint32_t v = scalarAt(i);
      if (v > maxSeen) maxSeen = v;
    }
  }

  // Streaming body: 128 bytes (8x movntdqa = TWO full cache lines) per
  // iteration, reduced in-register.
  //
  // NV-DXVK [perf]: was 64 bytes / one line per iteration folded into a single
  // accumulator. Two things limited it. (1) Reads from WC memory are served by
  // the core's line-fill buffers (~10-12 of them); one line in flight per
  // iteration leaves almost all of that memory-level parallelism unused, and
  // this loop is purely bandwidth-bound, so throughput tracks lines-in-flight.
  // (2) Every iteration's max depended on the previous iteration's `acc`, a
  // serial chain through a 1-cycle-throughput / multi-cycle-latency vmax.
  // Issuing two lines and reducing into two independent accumulators fixes
  // both; they merge once at the end. Still exact, still one pass.
  const uint32_t perIter = 128u / idxStride;  // 64 indices (u16) or 32 (u32)
  if ((count - i) >= perIter) {
    __m128i accA = _mm_setzero_si128();
    __m128i accB = _mm_setzero_si128();
    while ((count - i) >= perIter) {
      const __m128i* sv =
        reinterpret_cast<const __m128i*>(s + size_t(i) * idxStride);
      const __m128i v0 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 0));
      const __m128i v1 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 1));
      const __m128i v2 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 2));
      const __m128i v3 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 3));
      const __m128i v4 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 4));
      const __m128i v5 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 5));
      const __m128i v6 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 6));
      const __m128i v7 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 7));
      if (idxStride == 2u) {
        accA = _mm_max_epu16(accA,
                 _mm_max_epu16(_mm_max_epu16(v0, v1), _mm_max_epu16(v2, v3)));
        accB = _mm_max_epu16(accB,
                 _mm_max_epu16(_mm_max_epu16(v4, v5), _mm_max_epu16(v6, v7)));
      } else {
        accA = _mm_max_epu32(accA,
                 _mm_max_epu32(_mm_max_epu32(v0, v1), _mm_max_epu32(v2, v3)));
        accB = _mm_max_epu32(accB,
                 _mm_max_epu32(_mm_max_epu32(v4, v5), _mm_max_epu32(v6, v7)));
      }
      i += perIter;
    }
    const __m128i acc = (idxStride == 2u) ? _mm_max_epu16(accA, accB)
                                          : _mm_max_epu32(accA, accB);
    alignas(16) uint8_t lanes[16];
    _mm_storeu_si128(reinterpret_cast<__m128i*>(lanes), acc);
    if (idxStride == 2u) {
      for (int k = 0; k < 8; ++k) {
        uint16_t v; std::memcpy(&v, lanes + k * 2, 2);
        if (v > maxSeen) maxSeen = v;
      }
    } else {
      for (int k = 0; k < 4; ++k) {
        uint32_t v; std::memcpy(&v, lanes + k * 4, 4);
        if (v > maxSeen) maxSeen = v;
      }
    }
  }

  // Half-width remainder: 64..127 bytes left. Without this the tail below
  // would scalar-walk up to 63 indices straight off WC memory — one uncached
  // transaction each, which is the exact cost this function exists to avoid.
  const uint32_t halfIter = 64u / idxStride;
  if ((count - i) >= halfIter) {
    const __m128i* sv = reinterpret_cast<const __m128i*>(s + size_t(i) * idxStride);
    const __m128i v0 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 0));
    const __m128i v1 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 1));
    const __m128i v2 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 2));
    const __m128i v3 = _mm_stream_load_si128(const_cast<__m128i*>(sv + 3));
    const __m128i acc = (idxStride == 2u)
      ? _mm_max_epu16(_mm_max_epu16(v0, v1), _mm_max_epu16(v2, v3))
      : _mm_max_epu32(_mm_max_epu32(v0, v1), _mm_max_epu32(v2, v3));
    alignas(16) uint8_t lanes[16];
    _mm_storeu_si128(reinterpret_cast<__m128i*>(lanes), acc);
    if (idxStride == 2u) {
      for (int k = 0; k < 8; ++k) {
        uint16_t v; std::memcpy(&v, lanes + k * 2, 2);
        if (v > maxSeen) maxSeen = v;
      }
    } else {
      for (int k = 0; k < 4; ++k) {
        uint32_t v; std::memcpy(&v, lanes + k * 4, 4);
        if (v > maxSeen) maxSeen = v;
      }
    }
    i += halfIter;
  }

  // Tail.
  for (; i < count; ++i) {
    const uint32_t v = scalarAt(i);
    if (v > maxSeen) maxSeen = v;
  }
  return maxSeen;
}

// NV-DXVK [CbStage]: per-thread staged copies of mapped CONSTANT buffers.
// ExtractTransforms / the sky classifier read dozens of small fields out of
// mapped cb2/cb3 memory on EVERY draw — and those mappings are
// write-combined, where each scalar load is an uncached memory transaction
// (measured: [Perf.SubmitDraw] bt_extractXf ~52 ms/frame, spread across
// xt_srcFb / w2vw_cb3 / pv_validate / se2cb2). This cache stages a bound
// cbuffer into cached heap memory ONCE per content generation with a single
// streaming copy, so all subsequent field reads are ordinary cached loads.
//
// Safety: the cache key is (D3D11Buffer*, GetContentGeneration()). The
// generation is bumped on every Map(WRITE_DISCARD) — and DISCARD is the ONLY
// CPU write path D3D11 allows for dynamic constant buffers (11.0 has no
// NO_OVERWRITE or partial update for cbuffers), so an unchanged generation
// proves unchanged content. Do NOT use this for vertex/index/SRV buffers:
// those allow NO_OVERWRITE writes that do not bump the generation.
//
// cb2 is per-camera (one discard per frame, hundreds of draws) → one staging
// copy serves the whole frame. cb3 is per-object (discards per draw) → one
// 16-byte-wide streaming copy per draw replaces dozens of scattered uncached
// loads. Entries are a tiny linear-scan ring; consecutive draws bind the
// same few buffers so 8 entries cover the working set.
namespace {
  struct CbStageEntry {
    const void* buf = nullptr;   // D3D11Buffer* identity (never dereferenced on hit)
    uint64_t    gen = ~0ull;
    std::vector<uint8_t> bytes;
  };
  constexpr size_t   kCbStageEntries  = 8;
  constexpr size_t   kCbStageMaxBytes = 64 * 1024;  // don't stage giant buffers
}

// Forward decl — memcpyFromWC is defined above this block's first use.
static void memcpyFromWC(void* dst, const void* src, size_t len);

// Returns a cached-memory copy of `buffer`'s current mapped slice (and its
// length via lenOut), or nullptr when the buffer is unmapped / oversized —
// callers must fall back to their original direct-read path in that case.
template<typename D3D11BufferT>
static const uint8_t* stagedCbBytes(D3D11BufferT* buffer, size_t& lenOut) {
  lenOut = 0;
  if (buffer == nullptr) {
    return nullptr;
  }
  const auto mapped = buffer->GetMappedSlice();
  if (mapped.mapPtr == nullptr) {
    return nullptr;
  }
  const size_t len = std::min<size_t>(mapped.length, buffer->Desc()->ByteWidth);
  if (len == 0 || len > kCbStageMaxBytes) {
    return nullptr;
  }
  const uint64_t gen = buffer->GetContentGeneration();

  static thread_local std::array<CbStageEntry, kCbStageEntries> s_cbStage;
  static thread_local size_t s_cbStageNext = 0;

  for (CbStageEntry& e : s_cbStage) {
    if (e.buf == buffer && e.gen == gen && e.bytes.size() >= len) {
      lenOut = len;
      return e.bytes.data();
    }
  }

  CbStageEntry& e = s_cbStage[s_cbStageNext];
  s_cbStageNext = (s_cbStageNext + 1) % kCbStageEntries;
  e.buf = buffer;
  e.gen = gen;
  if (e.bytes.size() < len) {
    e.bytes.resize(len);
  }
  memcpyFromWC(e.bytes.data(), mapped.mapPtr, len);
  lenOut = len;
  return e.bytes.data();
}

// NV-DXVK [RdefCache]: single-entry per-thread memos for the hottest RDEF
// lookups. FindCBField / FindResourceSlot take const std::string& (the
// C++17 toolchain has no heterogeneous map lookup — see d3d11_shader.h:75),
// so every call with a literal heap-allocates temp strings and hashes two
// maps. These were still running per draw at several ExtractTransforms
// sites ([Perf.SdStall] xform segment, confirmed pure CPU). Draws batch by
// VS, so caching on the common-shader pointer makes them ~free. The
// templates avoid include-order coupling; only one instantiation exists.
// NV-DXVK [Perf.RdefMemo]: hit/miss for the memos below. Declared here rather
// than with the other counters further down because memoCamOriginLoc uses them.
std::atomic<uint64_t> g_rdefMemoHits   { 0 };
std::atomic<uint64_t> g_rdefMemoMisses { 0 };

// NV-DXVK [RdefCache] 2026-07-27: WIDENED FROM SINGLE-ENTRY TO 8-WAY.
//
// The original single-entry memos rested on the claim "Draws batch by VS" in the
// comment above. That was asserted, never measured. Measured now:
// [Perf.PrepSplit] rdefMemo hitPct = 71.5-73.8 across every window — so better
// than one draw in four MISSES and runs the string-keyed FindResourceSlot /
// FindCBField the memo exists to avoid (temp std::string heap-allocation plus
// two map hashes each).
//
// SIZE OF THE FIX, STATED HONESTLY: the whole resolve half measures 0.25-0.30
// us/call (4.2-4.9 ms/window of a ~1200 ms path, 0.38%), and the misses are
// essentially all of it. Widening recovers ~4 ms/window ≈ 0.03 ms/frame. It is
// a real defect and it is now correct, but it will NOT move frame rate — the
// 23-33 us/call in the map half is elsewhere. Do not expect this to show up in
// [Perf.Entry]; verify it in rdefMemo hitPct instead.
//
// 8 ways, linear scan, round-robin replacement. TF2 cycles through more than one
// shader per fanout batch but not dozens, so 8 covers the working set; if hitPct
// does not go to ~100 after this, raise kRdefMemoWays rather than reverting.
static constexpr size_t kRdefMemoWays = 8;

template<typename CommonShaderT>
static auto memoCamOriginLoc(const CommonShaderT* common)
    -> decltype(common->FindCBField("", "")) {
  using LocT = decltype(common->FindCBField("", ""));
  static thread_local const void* s_keys[kRdefMemoWays] = {};
  static thread_local LocT        s_vals[kRdefMemoWays] {};
  static thread_local size_t      s_next = 0;
  const void* key = static_cast<const void*>(common);
  for (size_t i = 0; i < kRdefMemoWays; ++i) {
    if (s_keys[i] == key) {
      g_rdefMemoHits.fetch_add(1, std::memory_order_relaxed);
      return s_vals[i];
    }
  }
  g_rdefMemoMisses.fetch_add(1, std::memory_order_relaxed);
  LocT loc = common->FindCBField("CBufCommonPerCamera", "c_cameraOrigin");
  s_keys[s_next] = key;
  s_vals[s_next] = loc;
  s_next = (s_next + 1u) % kRdefMemoWays;
  return loc;
}

// NV-DXVK [Perf.InstBufCache]: same question for m_instBufCache, the other
// single-entry cache in the fanout path — but this one lives in the map half
// that actually costs 21-27 us/call, and its miss path full-copies a
// std::vector rather than doing a map lookup. See the use site.
std::atomic<uint64_t> g_instBufCacheHits   { 0 };
std::atomic<uint64_t> g_instBufCacheMisses { 0 };
std::atomic<uint64_t> g_instBufCacheBytes  { 0 };

// NV-DXVK [Perf.BonePath]: which of the three bone-buffer read attempts wins.
// The map half of prep costs 15-26 us/call and three separate guesses at its
// contents have now been refuted (t31 memcpy — actually in loop; RDEF — already
// memoized at 0.18 us; instBufCache — 100% hit, zero copies). Rather than a
// fourth guess: attempt 1 is boneBufSlice.mapPtr(0), and mapPtr returns NULL for
// device-local buffers, in which case attempts 2 and 3 run on EVERY call. These
// counters say whether the chain short-circuits or runs to the end each time,
// and the paired marker says what that costs.
std::atomic<uint64_t> g_bonePathDirect { 0 };  // slice mapPtr hit
std::atomic<uint64_t> g_bonePathMapped { 0 };  // GetMappedSlice fallback
std::atomic<uint64_t> g_bonePathBuffer { 0 };  // GetBuffer()->mapPtr fallback
std::atomic<uint64_t> g_bonePathNone   { 0 };  // all three failed

// 8-way, same rationale as memoCamOriginLoc above. Each memo keeps its own table
// because the lookup key is (shader, resource-name) and the name is fixed per
// function — folding them into one table would halve the effective ways.
template<typename CommonShaderT>
static uint32_t memoModelInstSlot(const CommonShaderT* common) {
  static thread_local const void* s_keys[kRdefMemoWays] = {};
  static thread_local uint32_t    s_vals[kRdefMemoWays] = {};
  static thread_local size_t      s_next = 0;
  const void* key = static_cast<const void*>(common);
  for (size_t i = 0; i < kRdefMemoWays; ++i) {
    if (s_keys[i] == key) {
      g_rdefMemoHits.fetch_add(1, std::memory_order_relaxed);
      return s_vals[i];
    }
  }
  g_rdefMemoMisses.fetch_add(1, std::memory_order_relaxed);
  const uint32_t slot = common->FindResourceSlot("g_modelInst");
  s_keys[s_next] = key;
  s_vals[s_next] = slot;
  s_next = (s_next + 1u) % kRdefMemoWays;
  return slot;
}

template<typename CommonShaderT>
static uint32_t memoBoneMatrixSlot(const CommonShaderT* common) {
  static thread_local const void* s_keys[kRdefMemoWays] = {};
  static thread_local uint32_t    s_vals[kRdefMemoWays] = {};
  static thread_local size_t      s_next = 0;
  const void* key = static_cast<const void*>(common);
  for (size_t i = 0; i < kRdefMemoWays; ++i) {
    if (s_keys[i] == key) {
      g_rdefMemoHits.fetch_add(1, std::memory_order_relaxed);
      return s_vals[i];
    }
  }
  g_rdefMemoMisses.fetch_add(1, std::memory_order_relaxed);
  const uint32_t slot = common->FindResourceSlot("g_boneMatrix");
  s_keys[s_next] = key;
  s_vals[s_next] = slot;
  s_next = (s_next + 1u) % kRdefMemoWays;
  return slot;
}


// NV-DXVK [RdefCache]: same memo for the PS-side alpha-test lookup in
// FillMaterialData. Recovering TF2's in-shader clip() alpha test needs
// CBufUberStatic.c_alphaTestReference, and resolving it ran TWO string-keyed
// RDEF map lookups per draw (FindCBuffer + fields.find, each heap-allocating a
// temp std::string) on every draw that had not already picked up an alpha test
// from blend/stencil state — i.e. most draws. All of it is a pure function of
// the PS, so resolve once per shader.
struct AlphaTestRdefLoc {
  bool     valid    = false;  // field declared, used, and >= 4 bytes
  uint32_t bindSlot = UINT32_MAX;
  uint32_t offset   = 0;
  int      outcome  = 0;      // pre-computed static outcome (0/1/2), see call site
};

template<typename CommonShaderT>
static const AlphaTestRdefLoc& memoAlphaTestLoc(const CommonShaderT* common) {
  static thread_local const void* s_common = reinterpret_cast<const void*>(uintptr_t(-1));
  static thread_local AlphaTestRdefLoc s_loc {};
  if (static_cast<const void*>(common) != s_common) {
    s_common = common;
    s_loc = AlphaTestRdefLoc {};
    const auto* cbInfo = (common != nullptr) ? common->FindCBuffer("CBufUberStatic") : nullptr;
    if (cbInfo == nullptr
        || cbInfo->bindSlot >= D3D11_COMMONSHADER_CONSTANT_BUFFER_API_SLOT_COUNT) {
      s_loc.outcome = 0;  // no cbInfo / bad slot
    } else {
      const auto fieldIt = cbInfo->fields.find("c_alphaTestReference");
      if (fieldIt == cbInfo->fields.end()) {
        s_loc.outcome = 1;  // field not declared
      } else if (!fieldIt->second.used || fieldIt->second.size < sizeof(float)) {
        s_loc.outcome = 2;  // declared but unused — would carry stale data
      } else {
        s_loc.valid    = true;
        s_loc.bindSlot = cbInfo->bindSlot;
        s_loc.offset   = fieldIt->second.offset;
      }
    }
  }
  return s_loc;
}

// NV-DXVK TF2 BONE CAPTURE: global mirror populated by DxvkContext::copyBuffer
// when the game bulk-uploads rig matrices via staging→t30 copies. The
// D3D11 UpdateSubresource hook below only catches per-palette updates;
// those bulk copies are the source of upper-half bone data. Merge
// this mirror into m_fullBoneCache during skinning capture.
namespace dxvk { namespace tf2 {
  extern std::mutex g_boneCacheMirrorMutex;
  extern std::vector<uint8_t> g_boneCacheMirror;
  extern bool g_boneCacheMirrorPopulated;
  extern std::atomic<uint64_t> g_boneCacheMirrorGen;

  // NV-DXVK [EngineLightsCapture]: TF2's s_globalLights structured buffer
  // is DEVICE_LOCAL, so we mirror writes via the dxvk_context.cpp
  // copyBuffer/updateBuffer hooks. d3d11_rtx latches the buffer ptr the
  // first time it sees the SRV bound as s_globalLights, then the dumper
  // reads from g_lightBufferMirror.
  extern std::atomic<uintptr_t> g_lightBufferPtr;
  extern std::mutex             g_lightBufferMirrorMutex;
  extern std::vector<uint8_t>   g_lightBufferMirror;
  extern bool                   g_lightBufferMirrorPopulated;
  extern std::atomic<uint64_t>  g_lightBufferCopyWrites;
  extern std::atomic<uint64_t>  g_lightBufferUpdateWrites;
  extern std::atomic<uint64_t>  g_lightBufferTotalBytesWritten;
}}
